'use strict';
(()=>{
 const $=id=>document.getElementById(id),dialog=$('buildDialog');let data,categories,worker,generation=0,loading=false;
 const types={'great-sword':'대검','long-sword':'태도','sword-shield':'한손검','dual-blades':'쌍검',hammer:'해머','hunting-horn':'수렵피리',lance:'랜스',gunlance:'건랜스','switch-axe':'슬래시액스','charge-blade':'차지액스','insect-glaive':'조충곤','light-bowgun':'라이트보우건','heavy-bowgun':'헤비보우건',bow:'활'};
 // 거극 아티어: MHDB snapshot IDs for the fourteen weapon types.
 const gogArtianIds=WeaponBonuses.gogIds;
 const parts={weapon:'무기',head:'머리',chest:'상의',arms:'팔',waist:'허리',legs:'다리',talisman:'호석'};
 function option(select,value,label){const o=document.createElement('option');o.value=value;o.textContent=label;select.append(o);}
 function stop(message){generation++;worker?.terminate();worker=null;$('buildStart').disabled=!data;$('buildCancel').disabled=true;if(message)$('buildStatus').textContent=message;}
 function invalidate(){if(dialog.hidden)return;stop('조건이 변경되었습니다. 다시 검색하세요.');$('buildResults').replaceChildren();$('buildError').textContent='';}
 function weaponHint(){const w=data.weapons.find(w=>w.id===Number($('buildWeapon').value)),gog=gogArtianIds.has(w?.id);$('buildWeaponBonuses').hidden=!gog;for(const id of ['buildWeaponSeries','buildWeaponGroup']){if(!gog)$(id).value='0';$(id).disabled=!gog;}$('buildWeaponHint').textContent=gog?'거극 아티어의 시리즈·그룹 스킬을 아래에서 지정할 수 있습니다. 복원 보너스 수치는 반영하지 않습니다.':w?.category==='artian'?'아티어 기본 스킬·슬롯으로 계산합니다. 복원 보너스는 반영하지 않습니다.':'제작 무기의 강화 경로에서 마지막 단계만 표시합니다.';}
 function weapons(){const s=$('buildWeapon');s.replaceChildren();const choices=data.weapons.filter(w=>w.kind===$('buildType').value).sort((a,b)=>Number(gogArtianIds.has(b.id))-Number(gogArtianIds.has(a.id))||b.rarity-a.rarity||a.name.localeCompare(b.name,'ko'));for(const [category,label]of [['artian','아티어 · 기본 구성'],['crafted-final','제작 · 최종 강화']]){const group=document.createElement('optgroup');group.label=label;for(const w of choices.filter(w=>w.category===category))option(group,w.id,`${w.name} · R${w.rarity} · 슬롯 ${w.slots.join('/')||'없음'}`);if(group.children.length)s.append(group);}weaponHint();}
 function addGoal(){
  if($('buildGoals').children.length>=8)return;
  const row=document.createElement('fieldset');row.className='build-goal';const legend=document.createElement('legend');legend.textContent='목표 조건';row.append(legend);
  function field(label,tag,cls){const wrapper=document.createElement('label');wrapper.textContent=label;const control=document.createElement(tag);control.className=cls;wrapper.append(control);row.append(wrapper);return control;}
  const category=field('스킬 분류','select','build-category');option(category,'','전체 분류');for(const group of categories.groups)option(category,group.key,group.label);
  const query=field('이름·효과명 검색','input','build-skill-query');query.type='search';query.placeholder='예: 납도, 근성, 선전호응';
  const select=field('목표 스킬','select','build-skill');select.required=true;
  const levels=field('목표 레벨 / 효과','select','build-level');levels.required=true;
  const hint=document.createElement('p');hint.className='hint build-skill-count';hint.setAttribute('role','status');row.append(hint);
  function update(){levels.replaceChildren();const skill=data.skills.find(s=>s.id===Number(select.value));levels.disabled=!skill;if(!skill)return;for(const r of skill.ranks)option(levels,r.level,r.pieces?`${r.name} · ${r.pieces}부위`:`Lv.${r.level}`);}
  const normalize=s=>s.toLocaleLowerCase('ko').replace(/\s/g,'');
  function filter(){const previous=select.value,oldLevel=levels.value;select.replaceChildren();option(select,'','스킬을 선택하세요');let count=0;const needle=normalize(query.value);for(const group of categories.groups){if(category.value&&category.value!==group.key)continue;const options=data.skills.filter(s=>group.ids.includes(s.id)&&normalize([s.name,...s.ranks.map(r=>r.name||'')].join(' ')).includes(needle)).sort((a,b)=>a.name.localeCompare(b.name,'ko'));if(!options.length)continue;const og=document.createElement('optgroup');og.label=group.label;for(const skill of options)option(og,skill.id,skill.name);select.append(og);count+=options.length;}if([...select.options].some(o=>o.value===previous))select.value=previous;update();if([...levels.options].some(o=>o.value===oldLevel))levels.value=oldLevel;hint.textContent=count?`${count}개 스킬 · 목록에서 선택하세요.`:'일치하는 스킬이 없습니다. 검색어를 줄이거나 전체 분류로 바꾸세요.';}
  category.addEventListener('change',filter);query.addEventListener('input',()=>{filter();invalidate();});select.addEventListener('change',update);filter();
  const remove=document.createElement('button');remove.type='button';remove.textContent='조건 삭제';remove.addEventListener('click',()=>{row.remove();invalidate();});row.append(remove);$('buildGoals').append(row);
 }
 function text(parent,tag,value){const el=document.createElement(tag);el.textContent=value;parent.append(el);return el;}
 function render(result){const container=$('buildResults');container.replaceChildren();result.results.forEach((r,i)=>{const card=document.createElement('article');card.className='build-card';text(card,'h3',`세팅 ${i+1} · 최대 강화 방어력 ${r.defense}`);text(card,'p',r.achieved.map(g=>`${g.name} Lv.${g.level}${g.pieces!==null?` (${g.pieces}부위)` : ''}`).join(' / '));const list=document.createElement('ul');for(const item of [r.weapon,...r.armor])text(list,'li',`${parts[item.part||'weapon']}: ${item.name} · 슬롯 ${item.slots.join('/')||'없음'}`);card.append(list);if(r.weapon.selectedBonuses?.length)text(card,'p','무기 부여 스킬: '+r.weapon.selectedBonuses.map(b=>`${b.name} · 1부위`).join(' / '));text(card,'p',r.charm?`호석: ${r.charm.skills.map(s=>`${s.name} Lv.${s.level}`).join(' / ')} · 무기 ${r.charm.weaponSlots.join('/')||'없음'} · 방어구 ${r.charm.armorSlots.join('/')||'없음'} · ${r.charmOwned?'보유':'규칙 후보'}`:'호석: 사용하지 않음');if(r.decorations.length){text(card,'h4','장식주 배치');const jewels=document.createElement('ul');for(const p of r.decorations)text(jewels,'li',`${parts[p.owner]} ${p.index+1}번 ${p.kind==='weapon'?'무기':'방어구'} 슬롯[${p.size}]: ${p.decoration.name}`);card.append(jewels);}else text(card,'p','장식주: 필요 없음');if(r.activeBonuses.length)text(card,'p','발동 효과: '+r.activeBonuses.map(b=>`${b.name} — ${b.effect} (${b.pieces}부위)`).join(' / '));const save=document.createElement('button');save.type='button';save.className='primary save-build';save.textContent='이 세팅 저장';save.addEventListener('click',()=>{try{const snapshot=SavedBuilds.snapshot(r,data,$('buildMode').value);if(window.saveBuild(snapshot,`세팅 ${i+1}`)) {save.textContent='저장 완료';save.disabled=true;}}catch(e){$('buildError').textContent=e.message;}});card.append(save);container.append(card);});const limits={'result-limit':'대표 결과 20개 도달','time-limit':'20초 제한','node-limit':'탐색량 제한'};$('buildStatus').textContent=`${result.results.length}개 조합 · ${result.partial?`${limits[result.reason]||'제한'}으로 중단. 전체 탐색을 마치지 않았습니다.`:'지원 데이터 범위 검색 완료.'}${!result.results.length?' 조건을 낮추거나 호석 모드를 바꿔 보세요.':''}${result.excludedCharms?` 장비 데이터와 스킬이 맞지 않는 호석 후보 ${result.excludedCharms}건 제외.`:''}`;}
 dialog.addEventListener('page-enter',async()=>{if(data||loading)return;loading=true;$('buildStatus').textContent='장비 데이터를 불러오는 중…';try{const files=await Promise.all(['data/equipment-snapshot.json','data/skill-categories.json'].map(async url=>{const response=await fetch(url);if(!response.ok)throw Error('검색 데이터 요청 실패');return response.json();}));[data,categories]=files;for(const [id,kind]of [['buildWeaponSeries','set'],['buildWeaponGroup','group']])for(const skill of data.skills.filter(s=>s.kind===kind).sort((a,b)=>a.name.localeCompare(b.name,'ko')))option($(id),skill.id,`${skill.name} · ${skill.ranks.map(r=>r.name).join(' / ')}`);$('buildSource').textContent=`MHDB 데이터 반영: ${data.apiImportVersion} · 게임 버전 미확인`;for(const [key,value]of Object.entries(types))option($('buildType'),key,value);$('buildType').value='long-sword';weapons();addGoal();$('buildStart').disabled=false;$('buildStatus').textContent='목표 스킬을 선택하고 검색하세요.';}catch(e){$('buildError').textContent=e.message;}finally{loading=false;}});
 $('buildWeapon').addEventListener('change',weaponHint);$('buildType').addEventListener('change',()=>{weapons();invalidate();});$('buildAddGoal').addEventListener('click',()=>{addGoal();invalidate();});$('buildForm').addEventListener('change',invalidate);
 dialog.addEventListener('page-leave',()=>{if(worker)stop('페이지를 이동하여 검색을 취소했습니다.');});$('buildCancel').addEventListener('click',()=>stop('검색을 취소했습니다.'));let stateVersion=JSON.stringify([CandidateContext.get().inventoryVersion,CandidateContext.get().rulesVersion]);document.addEventListener('inventory-state-changed',()=>{const next=JSON.stringify([CandidateContext.get().inventoryVersion,CandidateContext.get().rulesVersion]);if(next!==stateVersion){stateVersion=next;invalidate();}});
 $('buildForm').addEventListener('submit',event=>{event.preventDefault();stop();$('buildError').textContent='';$('buildResults').replaceChildren();const request={weaponId:Number($('buildWeapon').value),weaponSeriesSkillId:Number($('buildWeaponSeries').value),weaponGroupSkillId:Number($('buildWeaponGroup').value),goals:[...$('buildGoals').children].map(row=>({id:Number(row.querySelector('.build-skill').value),level:Number(row.querySelector('.build-level').value)})),charmMode:$('buildMode').value,rank:$('buildRank').value,minDefense:Number($('buildDefense').value),records:window.CandidateContext.get().records};const token=generation;worker=new Worker('build-worker.js');$('buildStart').disabled=true;$('buildCancel').disabled=false;$('buildStatus').textContent='검색 준비 중…';worker.onmessage=({data:message})=>{if(token!==generation)return;if(message.type==='progress')$('buildStatus').textContent=message.phase==='charms'?`호석 후보 축소 중… ${message.examined||0}개 스킬 배정 확인`:`장비 탐색 중… ${message.nodes}회 / 결과 ${message.results}개`;else{stop();if(message.type==='error')$('buildError').textContent=message.message;else render(message);}};worker.onerror=()=>{stop();$('buildError').textContent='검색 작업을 실행하지 못했습니다. 새로고침 후 다시 시도하세요.';};worker.postMessage(request);});
})();
